import{_ as d,I as c,c as p,o as a,a5 as i,b as o,w as t,a as r,J as s,a6 as l}from"./chunks/framework.BmNIwhaK.js";const b=JSON.parse('{"title":"Empasy AI Software Development Lifecycle (Empasy AI-SDLC)","description":"A practical software development methodology that leverages SyncVerse and AI agents across every phase—from planning and design to implementation, verification, and deployment—to improve quality and productivity.","frontmatter":{"title":"Empasy AI Software Development Lifecycle (Empasy AI-SDLC)","description":"A practical software development methodology that leverages SyncVerse and AI agents across every phase—from planning and design to implementation, verification, and deployment—to improve quality and productivity.","head":[["meta",{"name":"keywords","content":"Empasy, AI Development Methodology, AI-SDLC, Software Development Lifecycle, Requirements Analysis, Spec-First Development, Automated Verification, Multi-Stage Approval, SyncVerse"}],["meta",{"property":"og:title","content":"Empasy AI Software Development Lifecycle (Empasy AI-SDLC) | Empasy Docs"}],["meta",{"property":"og:description","content":"A practical software development methodology that leverages SyncVerse and AI agents across every phase—from planning and design to implementation, verification, and deployment—to improve quality and productivity."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/methodology/ai-driven-development"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/methodology/ai-driven-development"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/methodology/ai-driven-development"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/methodology/ai-driven-development"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/methodology/ai-driven-development"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/methodology/ai-driven-development"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Empasy AI Software Development Lifecycle (Empasy AI-SDLC) | Empasy Docs"}],["meta",{"name":"twitter:description","content":"A practical software development methodology that leverages SyncVerse and AI agents across every phase—from planning and design to implementation, verification, and deployment—to improve quality and productivity."}]],"sort":100},"headers":[],"relativePath":"en/methodology/ai-driven-development.md","filePath":"en/methodology/ai-driven-development.md","lastUpdated":1795293539000}'),m={name:"en/methodology/ai-driven-development.md"};function g(h,e,u,f,y,A){const n=c("Mermaid");return a(),p("div",null,[e[2]||(e[2]=i('<h1 id="empasy-ai-software-development-lifecycle-empasy-ai-sdlc" tabindex="-1">Empasy AI Software Development Lifecycle (Empasy AI-SDLC) <a class="header-anchor" href="#empasy-ai-software-development-lifecycle-empasy-ai-sdlc" aria-label="Permalink to “Empasy AI Software Development Lifecycle (Empasy AI-SDLC)”">​</a></h1><blockquote><p><strong>Summary:</strong> The Empasy AI Software Development Lifecycle (Empasy AI-SDLC) is a practical engineering methodology that systematically orchestrates and verifies the entire software development lifecycle (SDLC)—from business requirements intake to architecture design, code implementation, automated testing, human-in-the-loop approval, and unattended deployment—through <strong>SyncVerse</strong>, Empasy&#39;s enterprise orchestration platform, and <strong>AI agents</strong>.</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Quick Links to Step-by-Step Practical Guides</p><p>Access hands-on guides and prompt examples for each phase of your project:</p><ul><li><strong><a href="./enterprise-project-lifecycle">Enterprise End-to-End Project Lifecycle (RFP to Go-Live)</a></strong>: End-to-end organizational operations from proposal to launch</li><li><strong><a href="./enterprise-action-items-guide">Phase-by-Phase Action Items &amp; SOP Guide</a></strong>: Concrete action items and standard operating procedures by phase</li><li><strong><a href="./presales-ai-playbook">Pre-Sales &amp; Proposal Playbook</a></strong>: RFP analysis, PoC demo creation, and effort estimation</li><li><strong><a href="./ai-sdlc-01-requirements">Phase 01: Planning &amp; Requirements Specification Guide</a></strong> (For Planners / POs)</li><li><strong><a href="./ai-sdlc-02-architecture">Phase 02: Spec-First Architecture &amp; DDL/API Design Guide</a></strong> (For Architects / Lead Developers)</li><li><strong><a href="./ai-sdlc-03-implementation">Phase 03: AI Collaborative Coding &amp; Autonomous Implementation Guide</a></strong> (For Developers)</li><li><strong><a href="./ai-sdlc-04-testing">Phase 04: Test Automation &amp; 4-Phase Automated Error Repair Guide</a></strong> (For QA / Developers)</li><li><strong><a href="./ai-sdlc-05-review-deploy">Phase 05: Code Review &amp; Unattended Deployment Guide</a></strong> (For Reviewers / Operators)</li><li><strong><a href="./ai-sdlc-prompt-recipes">Appendix: Practical Prompt Recipes by Scenario</a></strong> (For All Roles)</li></ul></div><hr><h2 id="_1-overview-definition" tabindex="-1">1. Overview &amp; Definition <a class="header-anchor" href="#_1-overview-definition" aria-label="Permalink to “1. Overview &amp; Definition”">​</a></h2><h3 id="_1-1-background-rationale-for-ai-driven-development" tabindex="-1">1.1. Background &amp; Rationale for AI-Driven Development <a class="header-anchor" href="#_1-1-background-rationale-for-ai-driven-development" aria-label="Permalink to “1.1. Background &amp; Rationale for AI-Driven Development”">​</a></h3><h4 id="limitations-of-traditional-software-development" tabindex="-1">Limitations of Traditional Software Development <a class="header-anchor" href="#limitations-of-traditional-software-development" aria-label="Permalink to “Limitations of Traditional Software Development”">​</a></h4><p>Traditional Waterfall and Agile workflows relied heavily on manual data entry and human memory:</p><ul><li><strong>Repetitive Work Fatigue</strong>: Significant engineering time was consumed by standardized tasks such as data model conversions, basic CRUD implementation, configuration files, and foundational unit tests.</li><li><strong>Semantic Drift in Communication</strong>: As a planner&#39;s intent passed through documents and tickets to developers, differences in interpretation frequently caused rework.</li><li><strong>Late Defect Discovery</strong>: Interface mismatches and regression bugs were often discovered only late in development or right before deployment, driving up remediation costs.</li><li><strong>Drift Between Documentation and Code</strong>: Under release deadline pressure, code changed while documentation went unupdated, making it difficult to trace system history.</li></ul><h4 id="benefits-and-paradigm-shift-of-empasy-ai-sdlc" tabindex="-1">Benefits and Paradigm Shift of Empasy AI-SDLC <a class="header-anchor" href="#benefits-and-paradigm-shift-of-empasy-ai-sdlc" aria-label="Permalink to “Benefits and Paradigm Shift of Empasy AI-SDLC”">​</a></h4><p>Empasy AI-SDLC goes beyond simple chatbot assistants by centrally orchestrating the entire engineering pipeline and cross-verifying deliverables at every phase. Using SyncVerse as the central orchestration engine, engineers move away from repetitive boilerplate coding and focus on system architecture design and core business logic verification.</p>',11)),(a(),o(l,null,{default:t(()=>[s(n,{id:"mermaid-101",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Traditional%20%5B%22Traditional%20Manual%20Development%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20T1%5B%22Manual%20Spec%20Writing%22%5D%20--%3E%20T2%5B%22Manual%20Design%20%26%20DDL%20Definition%22%5D%20--%3E%20T3%5B%22Manual%20Boilerplate%20Coding%22%5D%20--%3E%20T4%5B%22Post-Hoc%20Manual%20Testing%22%5D%20--%3E%20T5%5B%22Manual%20Deployment%20%26%20Monitoring%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20EmpasyAIDLC%20%5B%22Empasy%20AI-SDLC%20Development%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20A1%5B%22Requirements%20Intake%3Cbr%2F%3E(Natural%20Language%20Intent%20%2B%20Enterprise%20Knowledge%20Integration)%22%5D%20--%3E%20A2%5B%22Spec-First%20Design%3Cbr%2F%3E(UI%20Wireframe%20%26%20DDL%2FAPI%20Finalization)%22%5D%0A%20%20%20%20%20%20%20%20A2%20--%3E%20A3%5B%22AI%20Collaborative%20Coding%3Cbr%2F%3E(SyncVerse%20Wizard%20%26%20Coding%20Agents)%22%5D%0A%20%20%20%20%20%20%20%20A3%20--%3E%20A4%5B%224-Phase%20Regression%20Verification%3Cbr%2F%3E(Unattended%20Build%20%26%20Automated%20Error%20Repair)%22%5D%0A%20%20%20%20%20%20%20%20A4%20--%3E%20A5%5B%22Operator%20Review%20%26%20Unattended%20Deployment%3Cbr%2F%3E(Local%20Verification%20%26%20Multi-Stage%20Approval%20Before%20Deployment)%22%5D%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i('<table tabindex="0"><thead><tr><th style="text-align:left;">Comparison Area</th><th style="text-align:left;">Traditional Development</th><th style="text-align:left;">Empasy AI-SDLC</th><th style="text-align:left;">Expected Practical Impact</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Requirements Definition</strong></td><td style="text-align:left;">Writing dozens of pages of static documents</td><td style="text-align:left;">Conversational requirements refinement and automated spec structuring</td><td style="text-align:left;">Reduced misinterpretation across teams</td></tr><tr><td style="text-align:left;"><strong>Design Approach</strong></td><td style="text-align:left;">Incremental interface changes mid-implementation</td><td style="text-align:left;">Upfront finalization of data models (DDL) and API contracts</td><td style="text-align:left;">Guaranteed UI-to-server consistency</td></tr><tr><td style="text-align:left;"><strong>Code Implementation</strong></td><td style="text-align:left;">Developers manually authoring files from scratch</td><td style="text-align:left;">Automated generation of framework-standard code with AI collaboration</td><td style="text-align:left;">Faster delivery of core features</td></tr><tr><td style="text-align:left;"><strong>Quality Verification</strong></td><td style="text-align:left;">Post-hoc manual testing after implementation</td><td style="text-align:left;">4-phase iterative build verification and automated error repair loop</td><td style="text-align:left;">Earlier defect detection and higher stability</td></tr><tr><td style="text-align:left;"><strong>Deployment &amp; Operations</strong></td><td style="text-align:left;">Manual developer deployments and incident tracing</td><td style="text-align:left;">Unattended deployment and rollback after multi-stage operator approval</td><td style="text-align:left;">Deployment reliability and full auditability</td></tr></tbody></table><hr><h3 id="_1-2-goals-scope-of-application" tabindex="-1">1.2. Goals &amp; Scope of Application <a class="header-anchor" href="#_1-2-goals-scope-of-application" aria-label="Permalink to “1.2. Goals &amp; Scope of Application”">​</a></h3><h4 id="core-goals" tabindex="-1">Core Goals <a class="header-anchor" href="#core-goals" aria-label="Permalink to “Core Goals”">​</a></h4><ol><li><strong>Shorter Development Lead Time</strong>: Substantially reduce the end-to-end time from initial planning concepts to production-ready code.</li><li><strong>Built-In Software Quality</strong>: Finalize specifications before coding and run 4-phase regression verification to minimize runtime errors.</li><li><strong>Architectural Standardization</strong>: Consistently enforce enterprise-wide standard libraries (Lombok, AgentScope Java, etc.) and shared framework conventions.</li></ol><h4 id="phased-adoption-scope" tabindex="-1">Phased Adoption Scope <a class="header-anchor" href="#phased-adoption-scope" aria-label="Permalink to “Phased Adoption Scope”">​</a></h4><ul><li><strong>Stage 1 (Tool Assistance)</strong>: Developers use AI inside their IDE for code autocompletion and straightforward refactoring.</li><li><strong>Stage 2 (Feature-Level Autonomy)</strong>: Use the SyncVerse 4-phase wizard to handle specification extraction, code mutation, and build verification for individual features in one integrated flow.</li><li><strong>Stage 3 (Enterprise Collaborative Ecosystem)</strong>: Planners, developers, QA, and operators run the full development pipeline under central orchestration with formal approval workflows.</li></ul><hr><h3 id="_1-3-key-terminology" tabindex="-1">1.3. Key Terminology <a class="header-anchor" href="#_1-3-key-terminology" aria-label="Permalink to “1.3. Key Terminology”">​</a></h3><ul><li><strong>SyncVerse</strong>: Empasy&#39;s central orchestrator and control plane that coordinates all development and operational workflows.</li><li><strong>AI Agent</strong>: An autonomous execution unit that sequentially invokes required tools—such as file exploration, code authoring, and terminal command execution—to achieve a given objective.</li><li><strong>Domain Agent</strong>: A specialized agent dedicated to a specific business domain (SyncCMS: content, SyncShop: e-commerce, SyncBoot: shared backend, SyncLLM: AI gateway).</li><li><strong>Spec-First Development</strong>: An engineering approach in which database schemas and API input/output contracts are finalized before writing application code.</li><li><strong>Acceptance Criteria</strong>: Concrete completion conditions used to judge whether a planned feature has been implemented accurately.</li><li><strong>Auto Repair / Self-Healing</strong>: A procedure in which AI analyzes build or test failure logs, repairs the code autonomously, and re-runs the build.</li><li><strong>Human-in-the-Loop (HITL)</strong>: A safety control mechanism requiring human inspection and explicit approval before high-risk actions such as database changes, permission updates, or production deployments.</li></ul><hr><h2 id="_2-five-phase-flow-of-the-empasy-ai-sdlc" tabindex="-1">2. Five-Phase Flow of the Empasy AI-SDLC <a class="header-anchor" href="#_2-five-phase-flow-of-the-empasy-ai-sdlc" aria-label="Permalink to “2. Five-Phase Flow of the Empasy AI-SDLC”">​</a></h2><p>The Empasy AI-SDLC workflow progresses through <strong>Requirements Intake -&gt; Spec-First Design -&gt; Implementation -&gt; 4-Phase Verification -&gt; Review &amp; Deployment</strong>.</p>',13)),(a(),o(l,null,{default:t(()=>[s(n,{id:"mermaid-284",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20PO%20as%20Planner%20(PO)%0A%20%20%20%20actor%20Dev%20as%20Developer%20%2F%20Architect%0A%20%20%20%20participant%20SV%20as%20SyncVerse%20(Central%20Control%20Plane)%0A%20%20%20%20participant%20Agent%20as%20Coding%20Agent%0A%20%20%20%20participant%20Git%20as%20Remote%20Git%20Repository%0A%20%20%20%20participant%20CI%20as%20Unattended%20Deployment%20Pipeline%0A%0A%20%20%20%20Note%20over%20PO%2CSV%3A%20Phase%201%3A%20Requirements%20Intake%20%26%20Gap%20Discovery%0A%20%20%20%20PO-%3E%3ESV%3A%20Enter%20feature%20purpose%20in%20natural%20language%0A%20%20%20%20SV-%3E%3ESV%3A%20Search%20internal%20domain%20knowledge%20%26%20derive%20edge-case%20questions%0A%20%20%20%20SV--%3E%3EPO%3A%20Present%20structured%20functional%20spec%20%26%20screen%20layout%20draft%0A%20%20%20%20PO-%3E%3ESV%3A%20Finalize%20specification%0A%0A%20%20%20%20Note%20over%20Dev%2CSV%3A%20Phase%202%3A%20Spec-First%20Architecture%20%26%20DDL%2FAPI%20Design%0A%20%20%20%20SV-%3E%3ESV%3A%20Derive%20database%20schema%20(DDL)%20%26%20standard%20REST%20API%20contracts%0A%20%20%20%20SV--%3E%3EDev%3A%20Present%20table%20relationships%20%26%20API%20specification%0A%20%20%20%20Dev-%3E%3ESV%3A%20Lock%20interface%20contracts%20%26%20target%20file%20scope%0A%0A%20%20%20%20Note%20over%20Dev%2CAgent%3A%20Phase%203%3A%20AI%20Collaborative%20Coding%20%26%20Autonomous%20Implementation%0A%20%20%20%20SV-%3E%3EAgent%3A%20Instruct%20code%20generation%20within%20specified%20file%20scope%0A%20%20%20%20Agent-%3E%3EAgent%3A%20Author%20Spring%20Boot%20services%2C%20DTOs%2C%20and%20Vue%20UI%20components%0A%0A%20%20%20%20Note%20over%20Dev%2CAgent%3A%20Phase%204%3A%20Test%20Automation%20%26%20Automated%20Error%20Repair%0A%20%20%20%20Agent-%3E%3EAgent%3A%20Auto-generate%20unit%2Fintegration%20tests%20%26%20execute%20build%0A%20%20%20%20opt%20On%20build%20failure%20or%20test%20error%0A%20%20%20%20%20%20%20%20Agent-%3E%3EAgent%3A%20Analyze%20error%20logs%20%26%20auto-repair%20up%20to%203%20attempts%0A%20%20%20%20end%0A%20%20%20%20Agent-%3E%3EGit%3A%20Push%20working%20branch%20%26%20create%20Pull%20Request%20(PR)%0A%0A%20%20%20%20Note%20over%20Git%2CCI%3A%20Phase%205%3A%20Local%20Developer%20Verification%2C%20Multi-Stage%20Approval%20%26%20Deployment%0A%20%20%20%20Dev-%3E%3EGit%3A%20Check%20out%20working%20branch%20locally%20%26%20test%20directly%0A%20%20%20%20Dev-%3E%3ESV%3A%20Incorporate%20review%20feedback%20%26%20approve%0A%20%20%20%20SV-%3E%3ECI%3A%20Trigger%20unattended%20deployment%20pipeline%20after%20multi-stage%20approval%0A%20%20%20%20CI--%3E%3EDev%3A%20Notify%20deployment%20completion%20%26%20healthy%20system%20status%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<hr><h3 id="_2-1-phase-1-requirements-analysis-planning" tabindex="-1">2.1. Phase 1: Requirements Analysis &amp; Planning <a class="header-anchor" href="#_2-1-phase-1-requirements-analysis-planning" aria-label="Permalink to “2.1. Phase 1: Requirements Analysis &amp; Planning”">​</a></h3><ul><li><strong>Objective</strong>: Clarify planning intent and proactively uncover easily overlooked exception scenarios.</li><li><strong>Key Activities</strong>: <ul><li>The planner enters the background and goal of the feature in natural language.</li><li>SyncVerse queries the internal knowledge base (RAG) and asks the planner about missing edge cases (expiration, insufficient balance, duplicate requests, etc.).</li><li>Finalize user-perspective behavioral acceptance criteria (Given-When-Then format) and screen wireframes.</li></ul></li><li><strong>Detailed Practical Guide</strong>: <a href="./ai-sdlc-01-requirements">Phase 01: Planning &amp; Requirements Specification Guide</a></li></ul><hr><h3 id="_2-2-phase-2-spec-first-architecture-design" tabindex="-1">2.2. Phase 2: Spec-First Architecture Design <a class="header-anchor" href="#_2-2-phase-2-spec-first-architecture-design" aria-label="Permalink to “2.2. Phase 2: Spec-First Architecture Design”">​</a></h3><ul><li><strong>Objective</strong>: Finalize data models and API input/output contracts before coding to eliminate mismatches between server and frontend.</li><li><strong>Key Activities</strong>: <ul><li>Author the 6-file DDL schema (<code>00_extensions.sql</code> ~ <code>05_sample_dev.sql</code>) targeting PostgreSQL 18.6.</li><li>Eliminate temporary conflict-avoidance clauses (<code>ON CONFLICT</code>) and declare exact constraints and indexes.</li><li>Pre-define standard REST API endpoints (<code>/api/v1/{domain}/{resource}</code>) following the single-mapping principle.</li></ul></li><li><strong>Detailed Practical Guide</strong>: <a href="./ai-sdlc-02-architecture">Phase 02: Spec-First Architecture &amp; DDL/API Design Guide</a></li></ul><hr><h3 id="_2-3-phase-3-ai-collaborative-coding-autonomous-implementation" tabindex="-1">2.3. Phase 3: AI Collaborative Coding &amp; Autonomous Implementation <a class="header-anchor" href="#_2-3-phase-3-ai-collaborative-coding-autonomous-implementation" aria-label="Permalink to “2.3. Phase 3: AI Collaborative Coding &amp; Autonomous Implementation”">​</a></h3><ul><li><strong>Objective</strong>: Author source code rapidly and safely while adhering to enterprise architecture standards.</li><li><strong>Key Activities</strong>: <ul><li>Explicitly define the editable file scope (<code>focusFiles</code>) to isolate changes and prevent unintended side effects in other modules.</li><li>Backend: Enforce Lombok annotations, single canonical URL mapping, and AgentScope Java tool integration.</li><li>Frontend: Separate <code>BasicModal</code> components and follow database-driven dynamic menu routing.</li><li>Eliminate fake dummy responses (Mock) and ensure full live integration with the real database.</li></ul></li><li><strong>Detailed Practical Guide</strong>: <a href="./ai-sdlc-03-implementation">Phase 03: AI Collaborative Coding &amp; Autonomous Implementation Guide</a></li></ul><hr><h3 id="_2-4-phase-4-test-automation-4-phase-regression-verification" tabindex="-1">2.4. Phase 4: Test Automation &amp; 4-Phase Regression Verification <a class="header-anchor" href="#_2-4-phase-4-test-automation-4-phase-regression-verification" aria-label="Permalink to “2.4. Phase 4: Test Automation &amp; 4-Phase Regression Verification”">​</a></h3><ul><li><strong>Objective</strong>: Verify that authored code is free of syntax, interface, and business-logic defects, and repair errors autonomously when they occur.</li><li><strong>Key Activities</strong>: <ul><li>Automatically generate unit tests (JUnit 5, Vitest) covering exception scenarios.</li><li><strong>4-Phase Verification Loop</strong>: <ol><li>Source code compilation verification</li><li>API and DTO interface consistency verification</li><li>Business logic unit/integration test verification</li><li>Final clean packaging build verification</li></ol></li><li>When build errors occur, automatically repair code up to 3 attempts via <code>autoRepairCode</code>.</li></ul></li><li><strong>Detailed Practical Guide</strong>: <a href="./ai-sdlc-04-testing">Phase 04: Test Automation &amp; 4-Phase Automated Error Repair Guide</a></li></ul><hr><h3 id="_2-5-phase-5-code-review-safe-deployment" tabindex="-1">2.5. Phase 5: Code Review &amp; Safe Deployment <a class="header-anchor" href="#_2-5-phase-5-code-review-safe-deployment" aria-label="Permalink to “2.5. Phase 5: Code Review &amp; Safe Deployment”">​</a></h3><ul><li><strong>Objective</strong>: Enable human code verification and deploy reliably through a multi-stage approval workflow.</li><li><strong>Key Activities</strong>: <ul><li>AI automatically drafts a Pull Request (PR) summary detailing changes (Git Diff).</li><li>Developers check out the working branch in their local IDE, test directly, and leave inline feedback where needed.</li><li>Route high-risk changes through multi-stage approval (<code>Developer</code> -&gt; <code>QA</code> -&gt; <code>Admin</code>).</li><li>Execute unattended deployment, and apply configuration updates dynamically at runtime without restarting servers.</li></ul></li><li><strong>Detailed Practical Guide</strong>: <a href="./ai-sdlc-05-review-deploy">Phase 05: Code Review &amp; Unattended Deployment Guide</a></li></ul><hr><h2 id="_3-practical-engineering-tools-prompt-usage" tabindex="-1">3. Practical Engineering Tools &amp; Prompt Usage <a class="header-anchor" href="#_3-practical-engineering-tools-prompt-usage" aria-label="Permalink to “3. Practical Engineering Tools &amp; Prompt Usage”">​</a></h2><p>Ready-to-use prompts and rule configuration files for day-to-day engineering are provided in dedicated documents:</p><ul><li><strong><a href="./ai-sdlc-prompt-recipes">Practical Prompt Recipes by Scenario (Cheat Sheet)</a></strong>: Copy-and-paste templates for planning, DDL design, backend services, frontend modals, unit tests, and debugging.</li><li><strong>Shared Agent Rule Injection</strong>: Consistently configure enterprise standards (AgentScope Java, mandatory Lombok, single canonical URL, modal separation, Zero-Mock 4-Cycle verification) in <code>.agents/AGENTS.md</code> at the repository root and in IDE rule files (<code>.cursorrules</code>, <code>copilot-instructions.md</code>, etc.).</li></ul><hr><h2 id="_4-adoption-roadmap-performance-management" tabindex="-1">4. Adoption Roadmap &amp; Performance Management <a class="header-anchor" href="#_4-adoption-roadmap-performance-management" aria-label="Permalink to “4. Adoption Roadmap &amp; Performance Management”">​</a></h2><h3 id="phased-rollout-procedure" tabindex="-1">Phased Rollout Procedure <a class="header-anchor" href="#phased-rollout-procedure" aria-label="Permalink to “Phased Rollout Procedure”">​</a></h3><ol><li><strong>Pilot Operation (Months 1–2)</strong>: Select a pilot engineering team to trial Spec-First design and AI pair coding.</li><li><strong>Process Standardization (Months 3–4)</strong>: Integrate the 4-phase build verification and automated error repair loop into CI pipelines.</li><li><strong>Domain Agent Integration (Months 5–6)</strong>: Expand usage across domain-specific agents such as SyncCMS and SyncShop.</li><li><strong>Enterprise-Wide Institutionalization (Month 7+)</strong>: Establish an autonomous collaborative workflow where everyone from planners to operators communicates through SyncVerse.</li></ol><h3 id="key-performance-metrics" tabindex="-1">Key Performance Metrics <a class="header-anchor" href="#key-performance-metrics" aria-label="Permalink to “Key Performance Metrics”">​</a></h3><ul><li><strong>Development Lead Time</strong>: Track changes in total end-to-end lead time from feature planning to deployment.</li><li><strong>Early Defect Rate</strong>: Measure the number of defects requiring urgent hotfixes within 24 hours after deployment.</li><li><strong>Test Coverage</strong>: Track the ratio of automated test coverage across core business logic.</li><li><strong>Rework Rate</strong>: Monitor how often designs must be revised due to specification mismatches.</li></ul>',25))])}const D=d(m,[["render",g]]);export{b as __pageData,D as default};
